class SingleFlight:
    def __init__(self, loader):
        self._loader = loader
        self._inflight = {}  # key -> {"task": Task, "waiters": set[Future]}
        self._closed = False

    async def get(self, key):
        if self._closed:
            raise RuntimeError("SingleFlight is closed")
        entry = self._inflight.get(key)
        if entry is None:
            task = asyncio.create_task(self._loader(key))
            entry = {"task": task, "waiters": set()}
            self._inflight[key] = entry

            def _on_done(t, _key=key):
                # Cleanup race guard: remove the entry only if it still
                # refers to THIS task (a newer task may have replaced it).
                cur = self._inflight.get(_key)
                if cur is not None and cur["task"] is t:
                    del self._inflight[_key]
                # Retrieve the exception so it is never "never retrieved",
                # even if every waiter cancelled and nobody awaits it.
                if not t.cancelled():
                    t.exception()
            task.add_done_callback(_on_done)
        else:
            task = entry["task"]

        if task.done():
            # Task already finished (e.g. interleaving); propagate result.
            return task.result()

        loop = asyncio.get_running_loop()
        fut = loop.create_future()
        entry["waiters"].add(fut)

        def _relay(t):
            if fut.done():
                return
            if t.cancelled():
                fut.cancel()
            else:
                exc = t.exception()
                if exc is not None:
                    fut.set_exception(exc)
                else:
                    fut.set_result(t.result())
        task.add_done_callback(_relay)

        try:
            return await fut
        except asyncio.CancelledError:
            # This waiter was cancelled: detach only itself. The loader
            # task keeps running for remaining waiters (or alone).
            entry["waiters"].discard(fut)
            task.remove_done_callback(_relay)
            if not entry["waiters"] and not task.done():
                # Last waiter gone: nobody will await the result, but the
                # task must run to completion and its exception must still
                # be retrieved. _on_done already does the retrieval; keep
                # it attached and let the task finish in the background.
                pass
            raise

    async def close(self):
        self._closed = True
        tasks = [e["task"] for e in self._inflight.values() if not e["task"].done()]
        for t in tasks:
            t.cancel()
        if tasks:
            # Await them; return_exceptions ensures we also retrieve their
            # (CancelledError or loader) exceptions without raising.
            await asyncio.gather(*tasks, return_exceptions=True)
        self._inflight.clear()
